INSERT INTO "public"."universities" ("id", "organization", "eligible_countries", "notable_accolades", "education_levels", "fields", "minimum_gpa", "max_age", "required_documents", "application_url", "application_process", "number_of_recommendation_letters_required", "essays_required", "financial_aid_policy", "tuition_waiver_threshold", "accepted_application_platform", "application_fee", "country_located", "campus_locations", "university_type", "minimum_standardized_test_scores", "school_year_starting_date", "funding_type", "annual_tuitioin_coveratge_cost", "age_restrictions", "recommendation_letter_types", "program_delivery_mode", "english_proficiency_required", "need_blind", "sat_required", "accepted_english_proficiency_tests") VALUES
	('e3e07def-54cc-46ac-8aa2-731c17f544ec', 'Amherst College', '{"international students","domestic students",undocumented,DACA,"non-citizen permanent residents","those with fragile citizenship"}', '{"Athletics program is the oldest in the country","81 Division III individual titles and 14 team championships"}', '{undergraduate,graduate,"professional school"}', '{Arts,Humanities,"Science & Math","Social Sciences","Art and the History of Art","Film and Media Studies",Music,Classics,"Anthropology and Sociology",Physics,English,Economics,"European Studies","Environmental Studies","Statistics and Data Science"}', NULL, NULL, '{"Secondary school transcript","Teacher and counselor recommendations",essays,"writing supplement","standardized test results (optional / if submitted)"}', '', '', NULL, 'Amherst College Writing Supplement', 'Our financial aid offers only include grants, scholarships and student employment. Calculated need is met in full for all admitted students, including international and transfer students.', NULL, '{"Common Application","QuestBridge Application","Common App"}', NULL, 'United States', '{"New England"}', 'private liberal arts institution', '{}', '', '', NULL, '', '', '', true, true, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('2fa2a84c-ec57-4194-b554-51c2b912f3d9', 'Colgate University', '{"United States","international students (\"throughout the United States and around the world\")"}', '{"Colgate stands among the nation’s most distinguished small universities","competing at the Division I level."}', '{undergraduate}', '{"57 majors"}', 3.81, NULL, '{Application,"Two academic teacher recommendations","Guidance counselor recommendation","Official high school transcript","Mid-year grades","Early decision agreement (for ED applicants)"}', 'https://www.commonapp.org/', '', NULL, '', '100% demonstrated financial need met for students', NULL, '{"Common Application","Coalition Application on Scoir","QuestBridge Application","Common App"}', NULL, 'United States', '{Hamilton,"New York"}', 'private American university', '{"SAT: 1460–1530","ACT: 33–35"}', '', '', NULL, '', '', '', NULL, NULL, false, '{}'),
	('044cb163-bc2f-4edb-a29c-176817910c2b', 'Georgia Institute of Technology', '{"Any non-US citizen or non-US Permanent Resident is considered an international student for enrollment purposes."}', '{"Ranked No. 1 on the Princeton Review’s list of the Top 50 Best Value Colleges (Public Schools) for the fourth year; No. 1 for career placement; No. 1 for Best Value Colleges Without Aid; No. 2 for Best Schools for Internships; No. 5 for Best Alumni Network; No. 9 for Best Schools for Making an Impact; No. 5 public school (No. 27 overall) on Forbes’ 2027 list of America’s Best Colleges; A+ grade from Niche.com"}', '{undergraduate,graduate,doctoral}', '{Architecture,"Art & Design",Arts,Business,Communication,"Computer Science",Design,Economics,Engineering,Entertainment,Finance/Accounting,"Government/Political Science","Health Science","Liberal Arts",Music,Psychology,"Public health",Research,Science,"Social Science",Technology}', NULL, NULL, '{}', 'https://admission.gatech.edu/first-year', '', NULL, '', '', NULL, '{"Common App"}', '$85 for international applicants', 'United States', '{Atlanta,"GA 30332-0320","United States of America"}', 'Public', '{}', '', '', NULL, '', '', '', true, NULL, true, '{}'),
	('1f8716d5-ab43-432d-a137-1ef4c9c84b55', 'Yale University', '{"All countries; international applicants from all nationalities are eligible"}', '{"Ivy League member","Founded in 1701","Globally recognized private research university"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science",Engineering,Mathematics,Physics,Biology,Economics,"Political Science",Psychology,History,Philosophy,Chemistry,"Environmental Studies","Applied Mathematics"}', NULL, NULL, '{"Common Application, Coalition Application or QuestBridge application","Official secondary school transcript","School Report","Two teacher recommendation letters","SAT or ACT or qualifying alternative standardized examination results","Midyear Report when applicable","English proficiency examination when applicable","Certified English translations of documents not written in English"}', 'https://admissions.yale.edu/apply', 'Submit one application through Common Application, Coalition Application on Scoir or QuestBridge. Complete Yale-specific questions and essays, arrange submission of the school transcript and School Report, obtain two teacher recommendations and provide standardized test results. International applicants follow the same admissions process as domestic applicants. Apply through Single-Choice Early Action or Regular Decision.', '2', 'Common Application or equivalent personal essay plus Yale-specific short-answer questions and writing supplements. Prompts vary by application cycle.', 'Need-blind for international applicants. Yale meets 100% of demonstrated financial need for admitted students, including international students. Aid can cover tuition, housing, food and other eligible expenses. Financial assistance is need-based rather than merit-based.', NULL, '{"Common Application","Coalition Application on Scoir",QuestBridge}', '$80 USD; fee waivers may be available through eligible application platforms.', 'United States', '{"New Haven, Connecticut"}', 'Private research university', '{"SAT or ACT or qualifying AP/IB examination results under Yale''s test-flexible policy","No universal minimum admission score published"}', 'Fall semester, generally late August or early September.', 'Institutional need-based grants and scholarships.', NULL, 'No published maximum age. Applicants must satisfy first-year eligibility requirements.', 'Two academic recommendations from secondary school teachers, plus a counselor recommendation through the School Report.', 'Primarily in-person, residential undergraduate education.', true, true, false, '{TOEFL,IELTS,"Cambridge English Qualifications","Duolingo English Test"}'),
	('e336b307-4a77-4fcf-a881-3bd40f8faa10', 'Stanford University', '{"All countries; international applicants are eligible"}', '{"Private research university founded in 1885","Located in Silicon Valley","Member of the Association of American Universities","Recognized for engineering, computer science and entrepreneurship"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering",Bioengineering,Mathematics,Physics,Biology,Economics,"Management Science and Engineering","Political Science",Psychology,"Data Science","Environmental Science"}', NULL, NULL, '{"Common Application","Official secondary school transcript","School Report","Counselor recommendation","Two teacher recommendation letters","SAT or ACT scores","Midyear transcript","Personal essay and Stanford supplemental essays","Certified English translations when applicable"}', 'https://admission.stanford.edu/apply/first-year/', 'Apply through the Common Application. Submit Stanford''s supplemental questions, personal essay, academic records, counselor recommendation and two teacher recommendations. SAT or ACT scores are required. Applicants choose Restrictive Early Action or Regular Decision. International applicants are evaluated within the context of their educational system.', '3', 'Common Application personal essay, five short-answer questions and three Stanford supplemental essays. Exact prompts and word limits are updated annually.', 'International applicants may receive institutional need-based financial assistance. Stanford is need-aware for international students requesting aid, meaning financial need can affect admission. It meets the full demonstrated financial need of admitted students who requested aid during the admission process. It does not generally offer merit scholarships.', NULL, '{"Common Application"}', '$100 USD; fee waivers are available for eligible international applicants.', 'United States', '{"Stanford, California"}', 'Private research university', '{"SAT required or ACT required","No official minimum SAT or ACT score"}', 'Fall quarter, generally September.', 'Institutional need-based grants and limited athletic scholarships.', NULL, 'No published maximum age. Applicants who have enrolled in a degree-seeking university and earned credit after secondary school generally need to apply as transfer students.', 'One counselor recommendation and two academic recommendations from secondary school teachers.', 'In-person, residential undergraduate education.', false, false, false, '{}'),
	('7d0a8c48-b69b-4b8c-a3fd-bddf66007d75', 'Massachusetts Institute of Technology (MIT)', '{"All countries; no country-based international admission quotas"}', '{"Founded in 1861","Member of the Association of American Universities","Globally recognized in science, technology and engineering research","Strong entrepreneurship and innovation ecosystem"}', '{Undergraduate,"Bachelor of Science"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering","Artificial Intelligence",Mathematics,Physics,Chemistry,Biology,"Aerospace Engineering",Robotics,Economics,"Data Science","Chemical Engineering","Nuclear Science"}', NULL, NULL, '{"MIT-specific undergraduate application","Secondary School Report","Official secondary school transcript","Two teacher recommendation letters","SAT or ACT scores","MIT short-answer essays","English proficiency test results when applicable","February Updates and Notes form when applicable"}', 'https://mitadmissions.org/apply/firstyear/', 'Apply using MIT''s own application portal. Complete academic, personal and extracurricular sections and submit short-answer essays. Request two teacher recommendations and the Secondary School Report from the school counselor. SAT or ACT scores are required. International credentials are reviewed in the context of the student''s education system.', '2', 'Multiple short-answer essays covering academic interests, educational experiences, personal challenges and community contributions. Exact prompts change annually.', 'Need-blind admissions for international students. MIT meets 100% of demonstrated financial need for admitted undergraduates. Financial assistance includes institutional grants and scholarships rather than requiring students to finance their education through loans. The published 2026-2027 total cost of attendance is approximately $92,760 before financial aid.', NULL, '{"MIT Application Portal"}', '$75 USD; fee waivers are available for domestic and international applicants.', 'United States', '{"Cambridge, Massachusetts"}', 'Private research university', '{"SAT or ACT required","No official universal minimum SAT or ACT score","English proficiency examination strongly recommended for certain non-native English speakers"}', 'Fall semester, generally September.', 'Institutional need-based grants and scholarships.', NULL, 'No published maximum age for undergraduate admission. First-year and transfer eligibility rules apply.', 'One recommendation from a mathematics or science teacher and one from a humanities, social science or language teacher. Counselor School Report required.', 'In-person, residential undergraduate education.', false, true, false, '{TOEFL,IELTS,"Duolingo English Test","Pearson PTE Academic","Cambridge English Qualifications"}'),
	('eaa5d5b4-40b5-41c6-ad93-0e5adf945e76', 'California Institute of Technology (Caltech)', '{"All countries; international applicants are eligible"}', '{"Private STEM-focused research institution","Founded in 1891","Manages NASA''s Jet Propulsion Laboratory","Recognized for science, physics, mathematics and engineering research"}', '{Undergraduate,"Bachelor of Science"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering","Applied Physics",Physics,Chemistry,Mathematics,"Applied Mathematics",Biology,Bioengineering,"Geological and Planetary Sciences","Aerospace Engineering"}', NULL, NULL, '{"Common Application or QuestBridge application","Official secondary school transcripts","School Report","Two teacher recommendation letters","SAT or ACT scores","Caltech supplemental essays","English proficiency examination when applicable","Midyear academic report when available"}', 'https://www.admissions.caltech.edu/apply/first-year-applicants/international-applicants', 'Apply using the Common Application or QuestBridge. Submit academic records and standardized test results, request one STEM teacher recommendation and one humanities or social science teacher recommendation, and complete the Caltech-specific questions. Students with prior university enrollment generally must apply as transfer applicants.', '2', 'Common Application personal essay and Caltech supplemental short-answer questions and essays. Exact prompts change by application cycle.', 'Need-aware for international students. Caltech meets 100% of demonstrated financial need for admitted students receiving institutional aid. International students must request financial assistance when initially applying for admission; students who enroll without applying for or receiving aid generally cannot request it in later years, subject to limited exceptions.', NULL, '{"Common Application",QuestBridge}', '$85 USD; application fee waivers are available.', 'United States', '{"Pasadena, California"}', 'Private STEM research university', '{"SAT or ACT required","No universal minimum SAT or ACT score","Strong preparation in calculus, chemistry and physics expected"}', 'Fall term, generally September.', 'Institutional need-based grants and scholarships.', NULL, 'No published maximum age for admission. Additional minimum-age rules may apply to particular undergraduate housing arrangements.', 'One STEM teacher recommendation from calculus, chemistry, physics or biology, and one humanities or social science teacher recommendation.', 'In-person, residential undergraduate education.', true, false, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('6b1481d0-7d7c-4e5f-aa13-4f9f113e90fd', 'Johns Hopkins University', '{"All countries; international applicants are eligible"}', '{"Founded in 1876","Recognized as the first modern research university in the United States","Member of the Association of American Universities","Known for medicine, public health, engineering and scientific research"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science","Biomedical Engineering","Electrical Engineering","Mechanical Engineering","Applied Mathematics",Physics,Biology,Neuroscience,"Public Health",Economics,"International Studies","Data Science","Chemical and Biomolecular Engineering"}', NULL, NULL, '{"Common Application or Coalition Application","Secondary School Report","Official high school transcript","Two academic teacher evaluations","Counselor recommendation","SAT or ACT scores","Personal essay","Johns Hopkins supplemental essay","English proficiency results when applicable","International Student Certification of Finances"}', 'https://apply.jhu.edu/international-applicants/', 'Submit an application using Common Application or Coalition on Scoir. Complete the Hopkins supplemental essay, send official academic records, request two teacher recommendations and the counselor School Report, and submit SAT or ACT scores. International applicants must submit a Certification of Finances. Students applying for institutional need-based financial aid must indicate their intention in the admission application and submit the CSS Profile or eligible alternative form.', '2', 'Common Application or Coalition personal essay and a Johns Hopkins supplemental essay. The supplemental prompt changes each application year.', 'Need-aware for international applicants. Johns Hopkins meets 100% of demonstrated financial need for admitted students, including international students, without loans in its need-based aid packages. International students must request financial aid during their first-year admission process. Limited merit scholarships are also available.', NULL, '{"Common Application","Coalition Application on Scoir"}', '$70 USD; eligible application fee waivers may be requested.', 'United States', '{"Baltimore, Maryland","Washington, D.C. (additional academic and research facilities)"}', 'Private research university', '{"SAT or ACT required for first-year admission","No universal minimum admission score published"}', 'Fall semester, generally late August.', 'Institutional need-based grants and merit scholarships.', 68670, 'No published maximum age. Applicants with 12 or more semester-based college credits after secondary school may fall under transfer eligibility rules.', 'Two academic teacher evaluations from different subjects and a counselor recommendation through the Secondary School Report.', 'Primarily in-person, residential undergraduate education.', true, false, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('9eb7a182-c236-4b0b-8057-5f6773b2e868', 'Emory University', '{"All countries; international applicants are eligible"}', '{"Private research university founded in 1836","Member of the Association of American Universities","Associated with the Centers for Disease Control and Prevention''s Atlanta location","Recognized for medicine, business, public health and liberal arts"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science",Business,Economics,Biology,Neuroscience,Chemistry,Mathematics,"Environmental Sciences",Psychology,"Political Science",Physics,"Public Health","Quantitative Sciences"}', NULL, NULL, '{"Common Application","Official secondary school transcripts","School Report","Teacher recommendations","Common Application personal essay","Emory-specific short-answer responses","English proficiency results when applicable","Documentation of Finances","Bank statements for international applicants"}', 'https://apply.emory.edu/apply/international', 'Apply through the Common Application. Complete Emory''s additional questions and submit academic records, counselor documentation and teacher evaluations. International applicants must demonstrate English proficiency when applicable and provide financial certification and bank documentation. Applicants can apply through Early Decision or Regular Decision.', '2', 'Common Application personal essay plus two additional Emory-specific short-answer questions.', 'Emory provides need-based financial aid to a select group of international students each year. Financial documentation is required even for financial aid applicants, although applicants requesting aid do not need to demonstrate that they can independently cover the entire first-year cost. Merit scholarship opportunities are also available. International financial aid is competitive and not guaranteed.', NULL, '{"Common Application"}', '$75 USD; eligible applicants may request a fee waiver.', 'United States', '{"Atlanta, Georgia","Oxford, Georgia"}', 'Private research university', '{"SAT and ACT optional for the 2026-2027 application cycle","No universal minimum score for optional testing"}', 'Fall semester, generally August.', 'Institutional need-based financial aid and merit scholarships.', NULL, 'No published maximum age; first-year or transfer admission eligibility depends on previous university enrollment.', 'Two teacher evaluations from core academic subject teachers, in addition to the School Report.', 'In-person undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('b4873585-7caa-4d4d-9e8e-ba9de40f0005', 'Georgetown University', '{"All countries; international applicants are eligible"}', '{"Founded in 1789","One of the oldest Catholic and Jesuit universities in the United States","Recognized for international relations, government, law and business education"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science",Economics,"International Relations",Government,Business,Finance,Biology,Physics,Mathematics,Psychology,Linguistics,History,Nursing,"Environmental Biology"}', NULL, NULL, '{"Georgetown undergraduate application","Official secondary school transcript","School Report and counselor recommendation","Teacher recommendation","SAT or ACT scores","Georgetown-specific essays","Academic credentials from all secondary schools attended","English translations where applicable","English proficiency examination if submitted"}', 'https://uadmissions.georgetown.edu/apply/international-applicants/', 'Submit Georgetown''s undergraduate application, complete the Georgetown-specific writing supplements, provide academic records, recommendations and standardized test results. Georgetown requires SAT or ACT scores but may make exceptions when applicants are physically unable to access testing. International applicants are reviewed within the context of their educational systems. Financial aid requests must be declared during the application process.', '2', 'Georgetown personal statement and four Georgetown-specific writing responses, including two short essays and two longer essays. Exact prompts and limits are published for each cycle.', 'International students may be considered for a very limited number of need-based scholarships. International applicants must indicate that they intend to request financial aid during admission and submit the CSS Profile. Georgetown does not guarantee that all demonstrated financial need will be met for international applicants. International students should not confuse the university''s full-need policy for eligible US students with the limited international scholarship program.', NULL, '{"Georgetown Application"}', '$80 USD; fee waiver requests are accepted for international applicants experiencing financial hardship.', 'United States', '{"Washington, D.C."}', 'Private Jesuit research university', '{"SAT or ACT required","Exceptions may be considered when an applicant cannot physically access a testing center","No universal minimum score published"}', 'Fall semester, generally August.', 'Limited institutional need-based scholarships and external funding.', NULL, 'No published maximum age; applicants must satisfy first-year eligibility requirements.', 'One school counselor recommendation and one academic teacher recommendation.', 'In-person, campus-based undergraduate education.', false, false, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('b4e68641-2ba6-4521-bef9-8bf0fa5f5f73', 'George Washington University', '{"All countries; international applicants are eligible"}', '{"Private research university founded in 1821","Located in Washington, D.C.","Member of the Association of American Universities","Strong programs in international affairs, public policy and political science"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science",Engineering,"International Affairs","Political Science",Economics,Business,"Public Health",Biology,"Data Science",Psychology,Physics,Mathematics,Cybersecurity}', NULL, NULL, '{"Common Application or Coalition Application","Official high school transcript","School Report","One counselor or academic teacher recommendation","Personal essay","English proficiency documentation for relevant applicants","Financial certification form","Additional financial documents when admitted"}', 'https://undergraduate.admissions.gwu.edu/apply/international-applicants', 'Submit the Common Application or Coalition Application, complete the personal essay and provide school transcripts, a School Report and one recommendation. International applicants must demonstrate English proficiency when applicable and complete the Funding Your GW Education form. Admitted students provide further proof of sufficient funding.', '1', 'One Common Application or Coalition personal essay. An additional GW writing supplement may be submitted but is optional.', 'International students are not eligible for need-based institutional financial assistance. They may receive merit scholarships, which do not require an additional scholarship application. International applicants must independently demonstrate adequate funding for their studies.', NULL, '{"Common Application","Coalition Application"}', '$80 USD.', 'United States', '{"Foggy Bottom, Washington, D.C.","Mount Vernon Campus, Washington, D.C."}', 'Private research university', '{"SAT and ACT optional for most first-year applicants","Certain accelerated or special programs have additional testing requirements","No universal minimum score published"}', 'Fall semester, generally August.', 'Merit scholarships and external funding.', NULL, 'No published maximum age for admission.', 'One recommendation from a high school counselor or academic teacher.', 'In-person undergraduate education.', true, false, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('3d3e3e12-a807-4e8a-bf17-dae6ca7b46b2', 'Bucknell University', '{"All countries; international applicants are eligible"}', '{"Private liberal arts university founded in 1846","Member of the Patriot League","Known for undergraduate research and engineering education"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Engineering","Bachelor of Music"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering","Chemical Engineering","Civil Engineering",Mathematics,Physics,Biology,Economics,Psychology,Management,"Environmental Studies","Political Science"}', NULL, NULL, '{"Common Application or Coalition Application","Official high school transcript","Personal essay","School recommendation materials","Proof of financial support","Certified bank statement or Financial Certification Document","Passport copy","ISAFA for financial aid applicants","English proficiency evidence when required"}', 'https://www.bucknell.edu/admissions-aid/apply-bucknell/undergraduate-admission-requirements/admission-requirements-international-students', 'Apply using the Common Application or Coalition Application. Submit academic records and essays, pay the application fee or request an eligible waiver, and provide proof of financial support. International students seeking institutional aid must complete the International Student Application for Financial Assistance (ISAFA). A bank statement or Financial Certification Document is required for international application review.', NULL, 'Common Application or Coalition personal essay and any Bucknell-specific writing responses required by the selected application cycle.', 'Need-aware for international applicants. Bucknell provides limited and competitive need-based assistance to a small number of admitted international students. A few partial merit scholarships are also awarded. Students must apply for aid when initially applying; students who do not receive aid in their first year generally cannot obtain it in later years. The 2026-2027 undergraduate tuition is $72,600, and estimated total annual attendance cost is $97,716.', NULL, '{"Common Application","Coalition Application powered by Scoir"}', '$50 USD; eligible fee waiver requests may be submitted through the application platform.', 'United States', '{"Lewisburg, Pennsylvania"}', 'Private liberal arts university', '{"Test-optional status for previous cycles was documented; 2026-2027 continuation should be confirmed directly","No current universal minimum score established from the international admissions information"}', 'Fall semester, generally late August.', 'Limited institutional need-based aid and partial merit scholarships.', 72600, 'No published maximum age for admission.', 'Academic recommendations and counselor documentation; confirm the specific mandatory recommendation count for the application cycle.', 'Primarily in-person, residential undergraduate education.', true, false, false, '{TOEFL,IELTS,"Duolingo English Test","Pearson PTE Academic"}'),
	('948aa045-2017-4427-91be-b72af8bce88a', 'Mercer University', '{"All countries; international applicants are eligible"}', '{"Founded in 1833","One of Georgia''s oldest private universities","Known for engineering, business, liberal arts and health-related education"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Business Administration","Bachelor of Engineering"}', '{"Computer Science","Software Engineering","Electrical Engineering","Mechanical Engineering","Biomedical Engineering",Business,Economics,Chemistry,Biology,Mathematics,Psychology,"Political Science",Cybersecurity}', NULL, NULL, '{"Common Application or Mercer Application","Official high school transcript","Graduation certificate","Official English proficiency test score when required","Academic records and English translations","Proof of financial support","Passport and immigration documents when applicable"}', 'https://undergrad.mercer.edu/international-admissions/', 'Apply through the Common Application or Mercer Application. Submit official academic records and meet English language requirements. International applicants must provide financial information and supporting documents for immigration processing. Admission is reviewed in the context of the student''s academic background and program.', NULL, 'Personal essay or application writing responses according to the selected application platform; additional writing requirements depend on the program.', 'International applicants are eligible for merit-based scholarships but are not eligible for US federal or state financial aid. Merit awards depend on academic achievement and the university''s scholarship criteria. No universal full-need funding guarantee for international students is published.', NULL, '{"Common Application","Mercer Application"}', NULL, 'United States', '{"Macon, Georgia","Atlanta, Georgia","Other academic locations in Georgia"}', 'Private university', '{"SAT or ACT scores may be submitted depending on applicant circumstances and current testing policy","No universal international minimum score established from the admissions page"}', 'Fall semester, generally August.', 'Institutional merit scholarships and external scholarships.', NULL, 'No published maximum age for admission.', 'Recommendation requirements depend on the application and program; verify with undergraduate admissions.', 'Primarily in-person undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test","Pearson PTE Academic"}'),
	('9902088e-27c8-451e-ae6d-4123aced4b3c', 'Morehouse College', '{"All countries; international male applicants are eligible under the college''s undergraduate admission model"}', '{"Historically Black private liberal arts college","Founded in 1867","One of the leading historically Black men''s colleges in the United States","Known for leadership development and distinguished alumni"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science",Mathematics,Physics,Biology,Chemistry,Economics,"Business Administration","Political Science",Psychology,Sociology,English,History}', NULL, NULL, '{"Online admission application","Official high school graduation certificate","Official secondary school transcripts","Two recommendation letters","English proficiency examination when applicable","Official SAT or ACT results if available","Passport copy","Affidavit of Support","Certified bank statement for I-20 applicants"}', 'https://morehouse.edu/admissions/apply/international-freshmen', 'Complete the online international freshman application. Submit an official graduation certificate or national examination results, two recommendations, academic documents and required English proficiency evidence. SAT and ACT are optional. Applicants requiring an F-1 visa must submit an affidavit of support and certified sponsor bank statement.', '2', 'Application essay requirements depend on the online application and admission cycle; confirm the current prompts with the admissions office.', 'International applicants must provide proof of financial support for visa processing. The international admission page does not establish a universal need-based aid guarantee or a full-ride award for international students. Applicants should contact the university about institutional merit scholarships and external funding.', NULL, '{"Morehouse Online Application"}', NULL, 'United States', '{"Atlanta, Georgia"}', 'Private historically Black liberal arts college for men', '{"SAT and ACT optional for international freshmen","No minimum admission score published"}', 'Fall semester, generally August.', 'Institutional scholarship opportunities and external funding; international financial aid availability should be verified.', NULL, 'No published maximum age; the college''s undergraduate admission model is for men.', 'One recommendation from a guidance counselor or teacher and one from a community leader or comparable reference.', 'In-person, residential undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Cambridge English Qualifications","Pearson PTE Academic"}'),
	('2a756e59-ab17-4302-96b7-eddeb4b56a0d', 'Howard University', '{"All countries; international applicants are eligible"}', '{"Historically Black research university founded in 1867","Member of the Association of American Universities","Recognized for medicine, engineering, law, science and social sciences","Located in Washington, D.C."}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Engineering"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering",Architecture,Mathematics,Physics,Biology,Chemistry,Economics,"Political Science",Business,Psychology,Communications,Cybersecurity}', NULL, NULL, '{"Common Application","Official academic records for grades 9-12 or equivalent","Official external examination certificates or predicted grades","Academic credential evaluation where required","Two recommendation letters","Common Application personal essay","SAT or ACT scores if submitted","TOEFL or IELTS where applicable","Official English translations","HU International Student Financial Aid Application when seeking aid"}', 'https://admission.howard.edu/undergraduate/intl-first-year', 'Submit the Common Application and complete its personal essay and Howard-specific optional writing response. Provide official secondary academic records, recommendations, standardized testing information and English proficiency evidence. International students requesting institutional financial assistance must submit the HU ISFAA. Fall 2027 international first-year applications are open; early deadlines are November 1 and regular applications are due February 1.', '2', 'Common Application personal essay required; one Howard supplemental essay is optional.', 'International students and DACA students may apply for institutional financial assistance using the HU ISFAA. Scholarship decisions consider merit and available funding. Awards are not guaranteed, and the university does not publish an unconditional international full-need guarantee.', NULL, '{"Common Application"}', '$45 USD; the Common App fee waiver affirmation is accepted for eligible applicants experiencing financial hardship.', 'United States', '{"Washington, D.C."}', 'Private historically Black research university', '{"SAT and ACT optional for the 2026-2027 admission cycle for most first-year applicants","No universal minimum test score published"}', 'Fall semester, generally August.', 'Institutional merit-based scholarships and financial assistance through the HU ISFAA, subject to available funding.', NULL, 'No published maximum age for admission. Applicants previously enrolled in higher education must check first-year versus transfer eligibility.', 'One high school counselor recommendation and one high school teacher recommendation.', 'Primarily in-person undergraduate education.', true, NULL, false, '{TOEFL,IELTS}'),
	('d07c3a19-4554-4f75-9203-9b422828decd', 'University of Central Florida (UCF)', '{"All countries; international undergraduate applicants are eligible"}', '{"Public research university founded in 1963","Large undergraduate and graduate student community","Known for engineering, computing, hospitality and aerospace-related programs"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Engineering"}', '{"Computer Science","Information Technology","Electrical Engineering","Mechanical Engineering","Aerospace Engineering",Cybersecurity,"Data Science",Business,"Hospitality Management",Biology,Physics,Mathematics,"Digital Media"}', NULL, NULL, '{"UCF Undergraduate Application or Common Application","Official secondary school transcripts","Graduation certificate or national examination results","SAT, ACT or CLT scores","English proficiency evidence when applicable","Certified translations","Immigration and financial documentation for admitted international students"}', 'https://www.ucf.edu/admissions/undergraduate/international/', 'Apply through the UCF Undergraduate Application or Common Application for first-time-in-college applicants. Pay the application fee and submit all academic records, national examination results and required standardized test scores. Demonstrate English proficiency through approved tests or recognized alternative qualifications. International applicants must provide immigration documentation before enrollment.', '0', 'An application essay is strongly encouraged but not required for general freshman admission.', 'International undergraduate students are not eligible for federal financial aid, but UCF periodically offers scholarships to non-US citizens. Scholarship funding is limited and availability varies. The estimated 2026-2027 non-Florida resident tuition and fees are approximately $22,482, with an estimated full annual on-campus attendance cost of $43,832.', NULL, '{"UCF Undergraduate Application","Common Application"}', '$30 USD, non-refundable.', 'United States', '{"Orlando, Florida","Downtown Orlando, Florida","Other UCF regional campuses in Florida"}', 'Public research university', '{"SAT, ACT or CLT required for first-year admission","No universal minimum composite score established in the international applicant information","English proficiency alternatives include qualifying SAT or ACT English-related scores"}', 'Fall semester, generally August.', 'Limited institutional merit scholarships, departmental awards and external scholarships.', 22482, 'No published maximum age; first-year or transfer status depends on previous postsecondary credits.', 'No general recommendation letter requirement for freshman admission.', 'Primarily in-person undergraduate education, with selected online courses and programs.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('c9741a18-7fad-4f67-8994-b20f654917c2', 'University of Connecticut (UConn)', '{"All countries; international first-year applicants are eligible"}', '{"Public land-grant research university founded in 1881","Flagship public university of Connecticut","Recognized for engineering, business, agriculture and research"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Engineering"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering","Biomedical Engineering",Mathematics,Physics,Chemistry,Biology,Economics,Business,Psychology,Statistics,"Environmental Science"}', NULL, NULL, '{"Common Application or Coalition Application","Official secondary school transcripts","Official certified English translations","Personal essay","English proficiency examination when required","Financial documentation for international students","Optional recommendation letters"}', 'https://admissions.uconn.edu/apply/international/first-year/', 'Submit the Common Application or Coalition Application and pay the application fee. Provide official secondary school transcripts, graduation documentation and English translations where applicable. Submit English language test results if your primary language is not English. SAT or ACT scores are optional for first-year admission. Applicants can submit two optional recommendation letters.', '0', 'One personal essay through the Common Application or Coalition Application, generally 250-650 words.', 'International students generally do not qualify for US federal financial assistance. Institutional merit scholarship opportunities may be available, but substantial need-based funding for international undergraduates is limited and not guaranteed. Students requiring F-1 status must demonstrate adequate financial support for immigration documentation.', NULL, '{"Common Application","Coalition Application"}', '$80 USD, non-refundable.', 'United States', '{"Storrs, Connecticut","Hartford, Connecticut","Avery Point, Connecticut","Stamford, Connecticut","Waterbury, Connecticut"}', 'Public research university', '{"SAT and ACT optional for first-year admission","No minimum admission score required for applicants choosing not to submit tests"}', 'Fall semester, generally late August.', 'Limited merit scholarships, university awards and external scholarships.', NULL, 'No published maximum age. Applicants with 12 or more transferable postsecondary semester credits may be classified as transfer applicants.', 'Two optional recommendations from teachers or other academic references.', 'Primarily in-person undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test","LanguageCert Academic","Pearson PTE Academic"}'),
	('e463e03d-cb2f-4393-a18f-63c4c9a5dd17', 'University of Wisconsin-Madison', '{"All countries; international applicants are eligible"}', '{"Public flagship research university founded in 1848","Member of the Association of American Universities","Known for engineering, computer science, agriculture and scientific research"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Engineering"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering","Biomedical Engineering",Mathematics,Physics,Chemistry,Biology,Economics,Statistics,"Data Science",Agriculture,"Political Science",Business}', NULL, NULL, '{"Common Application or Universities of Wisconsin Application","Official secondary school transcripts","External national examination results","Certified English translations if applicable","English proficiency test results when applicable","Application essays and supplemental responses","Midyear or final academic results as required"}', 'https://admissions.wisc.edu/international/', 'Apply through the Common Application or Universities of Wisconsin Application. Submit official secondary school transcripts, required examination certificates and any applicable translations. Students educated in non-English-speaking countries must generally submit TOEFL, IELTS or Duolingo English Test results unless exempt. SAT and ACT are optional through the Spring 2028 term.', '0', 'Required application writing responses through the selected application platform; exact questions depend on the application cycle.', 'International students generally do not qualify for US federal need-based financial aid. Some institutional scholarships and external scholarships may be available, but international students should not assume that full-need assistance will be provided.', NULL, '{"Common Application","Universities of Wisconsin Application"}', NULL, 'United States', '{"Madison, Wisconsin"}', 'Public flagship research university', '{"SAT and ACT optional for applicants through Spring 2028","No minimum score required for test-optional admission"}', 'Fall semester, generally September.', 'Limited institutional scholarships and external scholarships.', NULL, 'No published maximum age for admission.', 'No general mandatory recommendation letter requirement established in the international admissions materials.', 'Primarily in-person undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('ea853b4a-430c-4fea-9587-a9d2a48e4294', 'University of California, Santa Barbara (UCSB)', '{"All countries; international first-year applicants are eligible"}', '{"Public research university in the University of California system","Member of the Association of American Universities","Recognized for physics, engineering, materials science and environmental research"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Engineering"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering","Chemical Engineering",Physics,Mathematics,Biology,Chemistry,Economics,"Environmental Science",Statistics,Psychology,"Political Science"}', NULL, NULL, '{"University of California Application","Secondary school academic records","National examination and qualification results","English proficiency examination when required","Certified translations when applicable","University of California Personal Insight Questions","Final transcript after admission"}', 'https://admissions.sa.ucsb.edu/international', 'Apply through the University of California''s centralized application portal. Complete the Personal Insight Questions, report academic history and examination results, and satisfy the relevant international curriculum requirements. Students whose secondary education was not conducted in English must demonstrate English proficiency. SAT and ACT scores are not considered in admission selection.', '0', 'Four Personal Insight Question responses selected from the University of California''s prompts, each with a maximum of 350 words.', 'International undergraduate students generally are not eligible for US federal or California state need-based financial aid. Institutional and external scholarship opportunities may exist, but international students should plan to cover the nonresident cost of attendance without assuming university-funded need-based assistance.', NULL, '{"University of California Application"}', '$95 USD per UC campus for international applicants.', 'United States', '{"Santa Barbara, California","Isla Vista, California"}', 'Public research university', '{"SAT and ACT are not used in undergraduate admission selection","International students may need English proficiency examination results"}', 'Fall quarter, generally late September.', 'Limited university scholarships and external scholarships; no general international need-based funding guarantee.', NULL, 'No published maximum age for admission; academic eligibility requirements apply.', 'No general recommendation letters are required unless specifically requested for certain programs or applicants.', 'Primarily in-person undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('58dde3e4-4f9e-4366-9aa8-a19398759030', 'Michigan Technological University', '{"All countries; international undergraduate applicants are eligible"}', '{"Public technological research university founded in 1885","Known for engineering, computing, science and technology","Strong undergraduate engineering and hands-on research opportunities"}', '{Undergraduate,"Bachelor of Science","Bachelor of Engineering"}', '{"Computer Science","Software Engineering","Electrical Engineering","Mechanical Engineering","Civil Engineering","Computer Engineering",Cybersecurity,"Artificial Intelligence","Data Science",Robotics,Physics,"Applied Mathematics","Environmental Engineering"}', NULL, NULL, '{"Common Application","Official secondary school transcripts","Official graduation or national examination records","English proficiency examination","English translations where needed","Documents requested through the Husky applicant portal","Financial and immigration documentation after admission"}', 'https://www.mtu.edu/admissions/apply/international/first-year/', 'Submit the Common Application and pay the international processing fee. After submission, review the Husky applicant portal for any additional required academic documents. International undergraduate applicants must meet English proficiency requirements for direct degree admission and submit required immigration documents after acceptance.', '0', 'No personal essay or additional recommendation letters should be submitted unless specifically requested through the university''s applicant portal.', 'Michigan Tech offers merit scholarships for international students. Some scholarships are awarded automatically based on eligibility, while others require separate applications. International applicants should budget for nonresident tuition and additional international student fees. Federal need-based financial aid is generally unavailable to international students.', NULL, '{"Common Application"}', '$35 USD, non-refundable; fee waivers are not approved for international applicants.', 'United States', '{"Houghton, Michigan"}', 'Public technological research university', '{"No universal SAT or ACT requirement established for the international first-year application","English proficiency minimums include TOEFL 79 for tests before January 21, 2026 or 4.5 on the newer scale, IELTS 6.5, Duolingo 120, or PTE 53","SAT EBRW 510 or ACT English and Reading 18 can satisfy certain English proficiency requirements"}', 'Fall semester, generally August; Spring semester, January.', 'International merit scholarships and competitive institutional awards.', NULL, 'No published maximum age for admission.', 'Recommendation letters are not generally requested unless specified in the applicant portal.', 'In-person, campus-based undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test","Pearson PTE Academic"}'),
	('70e99785-b38d-46c8-a7fe-bf1f16322d47', 'University of Oregon', '{"All countries; international undergraduate applicants are eligible"}', '{"Public research university founded in 1876","Member of the Association of American Universities","Known for business, journalism, architecture, education and environmental sciences"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science"}', '{"Computer Science","Data Science",Mathematics,Physics,Biology,"Business Administration",Economics,Psychology,"Political Science","Environmental Science",Journalism,Architecture,"Media Studies"}', 3.0, NULL, '{"Oregon Application or Common Application","Official high school transcripts","Graduation certificate when applicable","Personal statement when applicable","Optional recommendation letters","English proficiency evidence","Proof of financial support","Official English translations when required"}', 'https://www.uoregon.edu/admissions/undergraduate/find-your-path/international-students/', 'Apply through the Oregon Application or Common Application. Submit academic records showing secondary school coursework and grades. International first-year applicants are expected to have at least a B average, equivalent to approximately a 3.0 GPA. Meet English proficiency requirements or qualify for conditional admission. Provide evidence of financial support for immigration purposes. SAT and ACT scores are not required for international admission.', '0', 'Personal statement and recommendation letters are optional for general international admission, but can be submitted to explain circumstances affecting academic performance.', 'International students are eligible for merit-based scholarships, including awards for academic achievement and other university scholarship opportunities. Federal financial aid is generally unavailable to international students. Students should examine scholarship eligibility and award amounts before assuming that tuition will be covered.', NULL, '{"Oregon Application","Common Application"}', '$75 USD, non-refundable.', 'United States', '{"Eugene, Oregon","Portland, Oregon (additional academic facilities)","Bend, Oregon (additional academic facilities)"}', 'Public research university', '{"SAT and ACT not required for international undergraduate admission","No universal SAT or ACT minimum score"}', 'Fall term, generally late September.', 'Merit-based scholarships and external scholarship funding.', NULL, 'No published maximum age; first-year and transfer requirements depend on prior college enrollment.', 'Optional academic recommendations from teachers or other individuals familiar with the applicant''s academic performance.', 'In-person undergraduate education, with selected online learning options.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test"}'),
	('d134a16b-577b-481c-abe7-fa2b6053c25d', 'Binghamton University (SUNY)', '{"All countries; international undergraduate applicants are eligible"}', '{"Public research university in the State University of New York system","Known as a Public Ivy or New Ivy in some publications","Recognized for engineering, computer science, business and research"}', '{Undergraduate,"Bachelor of Arts","Bachelor of Science","Bachelor of Engineering"}', '{"Computer Science","Electrical Engineering","Mechanical Engineering","Industrial Engineering",Mathematics,Physics,Biology,Chemistry,Economics,Business,Psychology,"Data Science","Political Science","Environmental Studies"}', NULL, NULL, '{"International first-year application","Official secondary school transcripts for the most recent three years","English translations when applicable","English proficiency test results","National examination or graduation documents","Financial support documentation","International Student Financial Statement","Official bank statements"}', 'https://www.binghamton.edu/admissions/undergraduate/apply/international/first-year.html', 'Submit an international first-year application and pay the application fee unless applying during a university promotional free-application period. Send official transcripts directly from the school, submit English language proficiency results and provide financial documentation. After receiving the application, activate the applicant account to track outstanding documents and admission decisions.', NULL, 'Application writing requirements depend on the selected application platform and application cycle; check the current first-year application instructions.', 'International students generally cannot access US federal need-based financial assistance. Binghamton offers limited scholarships and other funding opportunities, but full-need institutional financial assistance is not guaranteed. Students seeking an F-1 or J-1 visa must prove sufficient financial resources to cover the first year of education.', NULL, '{"Binghamton University application process","Common Application or SUNY application, depending on the admission route"}', '$50 USD for international applicants; a promotional free application period is available October 19-November 2, 2026.', 'United States', '{"Vestal, New York (Binghamton University campus)"}', 'Public research university', '{"SAT and ACT are not generally required for admission under the test-optional policy","English proficiency alternatives include TOEFL, IELTS, Duolingo, Pearson PTE, Cambridge English and certain SAT/ACT or international curriculum results"}', 'Fall semester, generally August.', 'Limited institutional merit scholarships and external scholarships.', NULL, 'No published maximum age for admission.', 'Recommendation requirements should be verified in the current application checklist; international application requirements focus on transcripts, English proficiency and financial documentation.', 'Primarily in-person undergraduate education.', true, NULL, false, '{TOEFL,IELTS,"Duolingo English Test","Pearson PTE Academic","Cambridge English Qualifications"}'),
	('d4ba521f-a3cd-4b3d-be57-dbf6bf551f9d', 'University of Mississippi (Ole Miss)', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Mississippi''s flagship public university","Offers the Stamps Scholarship, which can cover full cost of attendance plus an enrichment fund"}', '{Undergraduate}', '{"Computer Science",Engineering,Business,"Natural Sciences","Social Sciences",Humanities,Education,"Health Professions"}', NULL, NULL, '{"Online undergraduate application","Official secondary-school transcripts and graduation certificate","Certified English translations when documents are not in English","English-proficiency evidence or approved waiver","Passport identification page","Financial documentation for the I-20 process after admission"}', 'https://olemiss.edu/admissions/undergraduate-admissions/application-process/international-students/', 'Apply through the Ole Miss application or Common App, pay the international application fee, and submit academic records and English-proficiency evidence. First-year competitive scholarships require a separate Freshman Scholarship Application after the admission application. Applicants who have completed post-secondary study should use the international transfer process.', NULL, 'No additional essay requirement was verified for the general international first-year application. Competitive programmes and scholarship applications may request additional written materials.', 'International students may receive merit scholarships. The Mississippi Premier award is listed at up to $28,893 per year for qualifying first-year students with a 3.9–4.0 GPA; lower award tiers are available. The Stamps Scholarship covers full cost of attendance plus a $12,000 enrichment fund and is highly competitive. The main competitive scholarship application deadline is January 10. Do not assume U.S. federal need-based aid is available to international students.', 93, '{"Ole Miss online application","Common Application"}', 'USD 75; non-waivable for international applicants according to the international application page', 'United States', '{"Oxford, Mississippi (main campus)"}', 'Public research university; flagship institution', '{"SAT/ACT are not generally required for international freshman admission; programme-specific requirements may apply","English proficiency examples: TOEFL iBT 79, IELTS Academic 6.0, Duolingo English Test 110, PTE Academic 53"}', NULL, 'Merit-based institutional scholarships; competitive full-cost scholarship; tuition awards', 28893, 'No published maximum age. Applicants must meet secondary-school credential requirements and applicable student-visa rules.', 'No universal recommendation-letter requirement was verified for general international freshman admission; competitive programmes may request academic references.', 'Primarily in-person, on-campus undergraduate study; selected online offerings do not replace F-1 full-time study requirements.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Approved secondary-school or international-curriculum English qualifications"}'),
	('d170d10e-f3fd-461f-8950-822910890097', 'University of Kansas', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Association of American Universities member","Offers more than 275 degree programmes"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences",Humanities,"Architecture and Design",Education,"Health Professions"}', 3.25, NULL, '{"Online international application","Official high-school transcripts","Proof of high-school graduation","English-proficiency scores or approved exemption","Passport and financial documents for immigration processing when requested","Academic records from every post-secondary institution attended if applying as a transfer student"}', 'https://world.ku.edu/apply', 'Complete KU''s online international application and submit the required school records and English-proficiency information. Students outside the United States have a May 1 Fall application deadline. Freshman merit scholarships are based on high-school GPA and require admission by the May 1 Fall deadline. Applicants with any post-secondary study after high school are classified as transfer applicants.', NULL, 'No universal international freshman essay requirement was verified on the international application checklist; programme-specific requirements may apply.', 'KU lists renewable GPA-based awards for international freshmen: USD 8,000–16,000 per year, with a published 3.25 GPA entry tier and a 3.95–4.00 GPA top tier. The maximum published freshman award is USD 64,000 over four years. These are merit awards, not full-cost need-based packages.', NULL, '{"KU online international application"}', NULL, 'United States', '{"Lawrence, Kansas (main campus)"}', 'Public research university; state flagship', '{"SAT/ACT are not required for most international freshman applicants","For full English proficiency, KU lists TOEFL iBT 79 on the previous scale or 4.5 on the TOEFL 1–6 scale, and IELTS Academic 6.5; programme and subscore rules may apply"}', NULL, 'Renewable GPA-based international merit scholarships; generally partial tuition support', 16000, 'No published maximum age. Post-secondary coursework after high-school graduation changes the applicant classification to transfer.', 'No universal recommendation-letter requirement verified for the general international freshman application.', 'Primarily in-person, on-campus undergraduate study; selected online programmes are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","PTE Academic","Duolingo English Test","Other KU-approved English-proficiency routes or exemptions"}'),
	('b9f88a1f-0aae-4dcc-9a57-23c8e1ca9924', 'University of Kentucky', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Association of American Universities member","Public land-grant research university"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health Sciences"}', 2.5, NULL, '{"University of Kentucky international application or Common App","Official secondary-school transcripts and graduation records","English translations of records where needed","English-proficiency score or approved exemption","Passport and proof of funding for immigration documentation","Supplementary scholarship materials for selective awards"}', 'https://international.uky.edu/apply/admission-requirements', 'Apply using the UK International Application or Common App. Submit official academic records and English-proficiency evidence. Most first-year academic scholarships are considered after admission, while selected awards require additional materials. The international Fall priority and principal freshman scholarship deadline is December 1. Students with post-secondary study after secondary school should use the transfer route.', NULL, 'No universal essay requirement was confirmed for standard international admission. The International Ambassador Scholarship requires supplementary materials, including a 500-word essay and recommendation letter according to the scholarship instructions.', 'International freshman merit awards include Bluegrass scholarships of USD 6,500–16,000 per year (published GPA tiers from 3.0), William C. Parker awards with holistic review and a 3.0 minimum, and the International Ambassador Scholarship ranging from USD 3,000 to 50% of tuition with a 2.5 GPA minimum. Awards are competitive/limited and are not a guarantee of full cost coverage.', 50, '{"University of Kentucky International Application","Common Application"}', 'USD 60', 'United States', '{"Lexington, Kentucky (main campus)"}', 'Public research university; land-grant institution', '{"SAT/ACT are optional for most applicants; required for some programmes including Engineering","English examples: TOEFL iBT 71 on the previous scale or 4.0 on the new 1–6 scale, IELTS Academic 6.0, Duolingo English Test 105"}', NULL, 'Merit scholarships; selective international scholarship; partial tuition awards', 16000, 'No published maximum age. Applicants must satisfy secondary-school completion and visa requirements.', 'A recommendation letter is required for the International Ambassador Scholarship; no universal letter requirement was verified for general admission.', 'Primarily in-person, on-campus undergraduate study.', true, NULL, false, '{"TOEFL iBT","TOEFL Essentials","IELTS Academic","Duolingo English Test","PTE Academic","Approved country-based English exemptions"}'),
	('b93d92b0-e032-4da2-8e1f-275fc505e818', 'Arizona State University', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Carnegie R1 research university","Large multi-campus public research university in the Phoenix metropolitan area"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health and Life Sciences"}', 3.0, NULL, '{"ASU application or Common App","Official secondary-school transcripts and graduation certificate","English-proficiency evidence or approved waiver","Passport and financial guarantee documents for visa processing","Any programme-specific prerequisites or supplemental material"}', 'https://admission.asu.edu/apply/international/first-year', 'Submit the ASU first-year international application or Common App, pay the application fee, and provide academic and English-proficiency records. International first-year students are automatically considered for the New American University Scholarship when they meet the applicable admission and scholarship requirements. ASU''s Fall 2027 priority date is November 1, 2026; the regular admission date is January 15, 2027.', '0', 'The standard ASU application does not require an essay or personal statement. Specific scholarship applications may ask for separate responses.', 'The New American University Scholarship is a merit award for eligible international freshmen, with published annual tiers up to USD 17,500 based on GPA. It is renewable for up to eight semesters subject to continued eligibility. It is not a need-based full-cost package; sponsored students may be ineligible under the scholarship rules.', NULL, '{"ASU online application","Common Application"}', 'USD 90 for international applicants', 'United States', '{"Tempe, Arizona","Downtown Phoenix, Arizona","Polytechnic campus, Mesa, Arizona","West Valley campus, Glendale, Arizona"}', 'Public research university', '{"SAT/ACT are not universally required; ASU evaluates academic course and GPA requirements","English score minimums vary by programme: typical non-engineering examples include TOEFL iBT 61 (or 3.5 on the new scale), IELTS 6.0 and Duolingo 95; some programmes require higher scores"}', NULL, 'Merit-based international scholarship; partial tuition award', 17500, 'No published maximum age. Applicants must meet first-year or transfer classification and secondary credential requirements.', 'No recommendation letters required for the standard ASU first-year application; a scholarship or specific programme may request references.', 'On-campus, online and selected hybrid undergraduate programmes; F-1 students must comply with in-person enrolment rules.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Other ASU-approved English proficiency routes"}'),
	('f52bdc2b-6e10-4ab5-ab32-2b4085cade05', 'University of South Florida', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Carnegie R1 research university","Multi-campus public university serving the Tampa Bay region"}', '{Undergraduate}', '{Engineering,Computing,Business,"Natural and Marine Sciences","Social Sciences","Arts and Humanities",Education,"Health Professions"}', NULL, NULL, '{"Common App or approved freshman application","Official secondary-school transcripts and graduation records","SAT, ACT or CLT scores meeting international subsection requirements","Passport and financial documents for I-20 processing","English translations of academic records where needed"}', 'https://www.usf.edu/admissions/international/admission-information/undergraduate/freshmen.aspx', 'Apply through the Common App and submit official school records and the required SAT, ACT or CLT subsection scores. USF publishes separate international freshman deadlines and materials deadlines. International merit scholarships are considered automatically when the complete Fall 2027 freshman application is submitted by January 15, 2027. TOEFL/IELTS/DET should not be assumed to replace USF''s specified standardized-test subsection requirements for applicants subject to them.', '0', 'No universal additional international freshman essay requirement was confirmed in the retrieved checklist; Common App responses and programme-specific items may apply.', 'USF offers limited merit-based nonresident tuition waivers to international freshmen. Published Green and Gold awards include a maximum Presidential level of approximately USD 11,000 per year, with lower Directors and Scholars awards. Waivers reduce eligible nonresident tuition only and do not cover housing, meals, books or other living expenses; awards are competitive and cannot be stacked on the same nonresident tuition portion.', NULL, '{"Common Application"}', 'USD 30', 'United States', '{"Tampa, Florida","St. Petersburg, Florida","Sarasota-Manatee, Florida"}', 'Public research university', '{"International freshman applicants must meet minimum subsection scores: SAT Evidence-Based Reading and Writing 490 and Math 480; or ACT Reading 19, English 17 and Math 19; or CLT Verbal+Writing 38 and Quantitative 16","USF states that TOEFL/IELTS/DET do not replace these specified subsection-score requirements for applicants subject to them"}', NULL, 'Competitive nonresident tuition waiver; merit-based partial tuition support', 11000, 'No published maximum age. Applicants must satisfy freshman classification and international visa requirements.', 'No standard recommendation letter requirement was confirmed for international freshman admission.', 'Primarily in-person across USF campuses; selected online and hybrid programmes are available.', true, NULL, true, '{"SAT Evidence-Based Reading and Writing subsection","ACT English and Reading subsections","CLT Verbal and Writing subsections"}'),
	('a3be5681-98f7-49da-8cd1-93a08339e479', 'Michigan State University', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Association of American Universities member","Carnegie R1 research university"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,Agriculture,"Natural Sciences","Social Sciences","Arts and Humanities",Education}', NULL, NULL, '{"MSU online application or Common App","Official secondary-school transcripts and graduation certificate","English-proficiency evidence or approved waiver","Passport and financial documentation for immigration processing","Academic records from all post-secondary institutions if applying as a transfer student"}', 'https://admissions.msu.edu/apply/international/apply-now', 'Apply online as an international first-year student and submit transcripts, English-proficiency evidence and required supporting documents. MSU asks applicants who have taken any college or university classes after high-school graduation to apply as international transfers. Fall 2027 Early Action requires the complete application and materials by November 1, 2026, and provides maximum scholarship consideration. Later applications may be reviewed while space remains.', NULL, 'The application may include the personal statement/essay required by the chosen application platform; no additional universal international essay requirement was verified.', 'International first-year applicants are automatically considered for limited merit scholarships. Published scholarship levels range from USD 3,000 to USD 18,000 per year. Awards are competitive and are not a full-cost or need-based aid guarantee. Transfer students have separate scholarship eligibility rules.', NULL, '{"MSU online application","Common Application"}', 'USD 75', 'United States', '{"East Lansing, Michigan (main campus)"}', 'Public research university; land-grant institution', '{"SAT/ACT are test-optional for international first-year admission","English examples: IELTS Academic 6.5, Duolingo English Test 110; TOEFL accepted under MSU''s current score-scale rules"}', NULL, 'Competitive merit scholarships; partial tuition support', 18000, 'No published maximum age. Applicants with any university coursework after secondary-school completion are generally classified as transfer applicants.', 'No universal recommendation-letter count was confirmed for the international freshman application; programme-specific requirements may apply.', 'Primarily in-person, on-campus undergraduate study; selected online programmes are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Other MSU-approved English proficiency routes"}'),
	('13c845d7-08d1-4247-b604-843ba50eb3db', 'University of New Hampshire', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"New Hampshire''s flagship public university","Public land-grant research institution"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences",Humanities,Education,"Health Sciences"}', 3.1, NULL, '{"Common App","Official secondary-school transcript and graduation record","At least one recommendation from a teacher or counsellor","English-proficiency score or approved waiver","Passport identification page","Financial documentation for immigration processing"}', 'https://www.unh.edu/admissions-aid/apply', 'Apply using the Common App and submit the transcript, recommendation and English-proficiency materials. Fall 2027 Early Action is November 15, with supporting documents due December 12; Regular Decision is February 1. Some international scholarships require financial need and separate eligibility review; UNH may invite qualifying students to apply for additional institutional awards.', '1', 'Common App personal essay is part of the application route; additional programme or scholarship materials may be requested.', 'UNH offers limited merit scholarships to international undergraduates. Its International Engagement and Service Scholarship provides partial tuition support to qualifying students with financial need and strong academic/service records. Some additional awards invite students with a GPA around 3.1 or higher to apply. Do not assume federal aid or full demonstrated-need coverage for international students.', NULL, '{"Common Application"}', 'USD 65', 'United States', '{"Durham, New Hampshire (main campus)","Manchester, New Hampshire (selected programmes)"}', 'Public research university; flagship and land-grant institution', '{"SAT/ACT test-optional for general admission","English examples: TOEFL iBT 80 on the previous scale or 4.0 on the 1–6 scale, IELTS Academic 6.5, Duolingo English Test 120, PTE Academic 59"}', NULL, 'Merit scholarships and limited partial tuition / need-sensitive institutional awards', NULL, 'No published maximum age. Applicants must meet secondary-school completion and visa requirements.', 'At least one teacher or school counsellor recommendation is required for the standard first-year application.', 'Primarily in-person, on-campus undergraduate study; selected online and hybrid programmes are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","TOEFL Essentials",LanguageCert}'),
	('c734c3e3-49d6-444b-8d94-1473ee7287f1', 'University of Minnesota Twin Cities', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Association of American Universities member","Carnegie R1 research university"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,Agriculture,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health Sciences"}', NULL, NULL, '{"Common App","Self-reported secondary-school courses and grades as required in the application","English-proficiency score or approved waiver","Certification of Finances form for international applicants","Official academic records when requested after application/admission","Passport and financial documents for the I-20 process"}', 'https://admissions.tc.umn.edu/admissions/international-admissions/first-year-international-applicants', 'Apply through the Common App and complete the international applicant checklist, including self-reported academic information and the Certification of Finances form. Fall 2027 deadlines are Early Action I November 1, Early Action II December 1 and Regular Decision January 1. A completed application by the relevant deadline is used for scholarship consideration. SAT/ACT are test-optional for Fall 2027.', '0', 'No admission essay or recommendation letter is required in the standard Fall 2027 first-year checklist; Common App may include optional writing sections.', 'The Global Excellence Scholarship offers international freshmen approximately USD 5,000–20,000 per year, renewable for up to four years. It is a merit award applied toward tuition/nonresident tuition and requires a complete admission application and Certification of Finances form. It is not a guaranteed full-cost award.', NULL, '{"Common Application"}', 'USD 55', 'United States', '{"Minneapolis, Minnesota","St. Paul, Minnesota"}', 'Public research university; land-grant institution', '{"SAT/ACT test-optional for Fall 2027 first-year admission","English examples: TOEFL iBT 4.5 on the new 1–6 scale, IELTS Academic 6.5, Duolingo English Test 120, PTE Academic 59"}', NULL, 'Merit-based international scholarship; partial tuition support', 20000, 'No published maximum age. Applicants must meet first-year or transfer classification and visa requirements.', 'No recommendation letters required for standard first-year admission.', 'Primarily in-person across the Twin Cities campuses; selected online and hybrid programmes exist.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Other university-approved English proficiency routes"}'),
	('561ce3e3-2a87-4cb0-a32e-f9468c93c253', 'University of Houston', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Carnegie R1 research university","Urban public research university in Houston"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences","Arts and Humanities",Education,Architecture,"Hospitality Management"}', NULL, NULL, '{"Common App or ApplyTexas application","Official secondary-school transcript and graduation certificate","English-proficiency score or waiver","Application essay and resume","Passport and financial documentation for visa processing","Recommendation letter for Tier One Scholarship applicants"}', 'https://www.uh.edu/undergraduate-admissions/apply/international/international-freshman/international-freshman-process/', 'Apply through Common App or ApplyTexas. All applicants submit an essay and resume. Assured admission pathways include top 10% class rank, a 3.5 GPA, or SAT 1250/ACT 26, alongside the English requirement; applicants outside those pathways may receive holistic review. The Fall 2027 international application deadline is May 3, 2027, with supporting documents due May 10. Tier One Scholarship applicants must meet the November 2, 2026 priority date and submit the scholarship application and recommendation materials.', '0', 'An essay and resume are required for all international freshman applicants. Applicants to the Tier One Scholarship also submit a separate scholarship application and a recommendation letter.', 'The Tier One Scholarship is a highly competitive award that can cover full tuition and mandatory fees plus two years of on-campus housing and meals. The exact dollar value depends on the student''s programme and published cost of attendance. It is not a general guaranteed award for international applicants. Other international merit aid is limited; do not assume need-based full-cost aid.', 100, '{"Common Application",ApplyTexas}', 'USD 90', 'United States', '{"Houston, Texas (main campus)"}', 'Public research university', '{"SAT/ACT are not required for every applicant; one assured-admission route is SAT 1250 or ACT 26, with a separate 3.5 GPA or top-10%-class-rank route","English examples: TOEFL iBT 4.0 on the new 1–6 scale, IELTS Academic 6.5, Duolingo English Test 105"}', NULL, 'Highly competitive full-tuition-and-fees scholarship with limited housing/meals support; other merit awards may be partial', NULL, 'No published maximum age. Applicants with 15 or more transferable post-secondary credits may be classified under a different admission route; confirm directly with UH.', 'One recommendation letter is required for the Tier One Scholarship; not required for general freshman admission based on the retrieved checklist.', 'Primarily in-person at the Houston campus; selected online and hybrid undergraduate programmes are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","Other UH-approved English proficiency routes"}'),
	('182574f2-05ba-4c41-be1d-89232c71284d', 'Washington State University', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Carnegie R1 research university","Public land-grant research university"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,Agriculture,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health Sciences"}', 3.0, NULL, '{"Online international undergraduate application","Official secondary-school transcripts","Proof of English proficiency or approved waiver","Passport identification page or national identity document","Proof of funds for I-20 processing after admission"}', 'https://ip.wsu.edu/future-students/how-to-apply-undergraduate/', 'Submit the WSU international undergraduate application and upload official transcripts, English-proficiency evidence and passport identification. WSU uses rolling admission, with April 15 as the Fall priority date; the published international Fall application deadline is June 15 and required documents are due July 1. New international scholarship awards have separate eligibility rules and a December 15 Fall deadline. Applicants with post-secondary coursework should confirm first-year versus transfer scholarship eligibility.', '0', 'Personal statements and recommendation letters are welcomed but are not generally required for the standard international undergraduate application.', 'New international freshmen may qualify for the International Academic Award, with published automatic awards of USD 2,000–4,000 per year based on GPA. Other awards have separate eligibility and may require WSU credits. These are partial merit awards, not full-cost aid.', NULL, '{"WSU online international application","Common Application","Cialfo where applicable"}', 'USD 70', 'United States', '{"Pullman, Washington (main campus)","Spokane, Washington","Tri-Cities, Washington","Vancouver, Washington","Everett, Washington"}', 'Public research university; land-grant institution', '{"SAT/ACT are not required for standard international admission","English tests and minimums depend on proficiency pathway; accepted options include TOEFL iBT, IELTS Academic, Duolingo English Test and PTE Academic"}', NULL, 'Automatic international merit tuition award; additional competitive scholarships', 4000, 'No published maximum age. Secondary credentials and visa requirements apply.', 'Letters of recommendation are optional; the university may request additional information during review.', 'In-person at WSU campuses, with selected online/hybrid programmes; F-1 students must meet in-person study rules.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Other WSU-approved English proficiency routes"}'),
	('b180b259-70aa-4933-bd94-e1aba3601c59', 'Eckerd College', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Private liberal arts college with a waterfront campus","Known for marine and environmental science-related study"}', '{Undergraduate}', '{"Marine Science","Environmental Studies",Biology,"Computer Science",Business,Psychology,Humanities,"Social Sciences"}', NULL, NULL, '{"Eckerd application or Common App","Official secondary-school transcripts and national examination results","Certified English translations where needed","One recommendation letter","Personal statement or essay","English-proficiency evidence","Passport and bank statement/financial documentation"}', 'https://www.eckerd.edu/admissions/international/', 'Apply through the Common App or Eckerd''s own application. Submit secondary-school records, national examination results, an essay, recommendation and English-proficiency evidence. International applicants are considered through Early Action by November 15 or Rolling Admission after that date; completed rolling applications usually receive decisions within about four weeks. International first-year scholarships are considered automatically.', '1', 'A personal statement/essay is required as part of the application.', 'International first-year students may receive an automatic International Student Grant of up to USD 27,000 per year, depending on academic strength. International students are not eligible for Eckerd need-based institutional aid according to the international scholarship information; talent awards may be available separately. The grant is partial and does not guarantee full cost coverage.', NULL, '{"Common Application","Eckerd College application"}', 'USD 50', 'United States', '{"St. Petersburg, Florida (main campus)"}', 'Private nonprofit liberal arts college', '{"SAT/ACT are test-optional for admission","English examples: TOEFL iBT 79 (or 4.0 on the new scale), IELTS Academic 6.5, Duolingo English Test 110; SAT EBRW 550 or ACT English+Reading 43 may satisfy the English requirement"}', NULL, 'International merit grant; partial tuition scholarship; separate talent awards may exist', 27000, 'No published maximum age. Applicants who have enrolled in post-secondary coursework after high school may be classified as transfer students.', 'One academic recommendation from a teacher or school official is required according to the international checklist.', 'Primarily residential, in-person undergraduate study at the St. Petersburg campus.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","SAT Evidence-Based Reading and Writing","ACT English and Reading","Other approved English-medium education routes"}'),
	('3eeb6a22-df2c-4afc-8d5e-7ace4b39bd90', 'University of St. Thomas (Minnesota)', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Private Catholic university","Twin Cities campus location"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences",Humanities,Education,"Health Sciences"}', NULL, NULL, '{"Common App or St. Thomas first-year application","Official high-school transcripts","English-proficiency score or approved waiver","Passport and proof of financial support for immigration documentation","Optional essay and recommendation materials","Post-secondary transcripts if applying as a transfer student"}', 'https://www.stthomas.edu/admissions/undergraduate/first-year/', 'Apply free through the Common App or St. Thomas first-year application. Submit high-school transcripts and any required English-proficiency evidence. Fall 2027 Early Action is November 1 and Regular Decision is January 15, followed by rolling review. Applicants who have attended a college or university after secondary school should use the transfer application process.', NULL, 'Essay questions are part of the application checklist; confirm the current optional/required status in the live application. Recommendation materials may be submitted but are not universally required in every pathway.', 'International students may receive renewable merit scholarships ranging from approximately 10% to 70% of tuition, with published average awards around 50–60%. Scholarships are not full-ride awards and do not normally cover living expenses. Renewal requires continued academic eligibility.', 70, '{"Common Application","University of St. Thomas first-year application"}', 'USD 0', 'United States', '{"St. Paul, Minnesota","Minneapolis, Minnesota"}', 'Private nonprofit Catholic university', '{"SAT/ACT optional","English examples: TOEFL iBT 79 (or 4.0 new scale), IELTS Academic 6.0, Duolingo English Test 105, PTE Academic 53"}', NULL, 'Renewable international merit scholarship; partial tuition discount', NULL, 'No published maximum age. Applicants who have attended a college or university after secondary school are generally transfer applicants.', 'Recommendation letters may be submitted; no universal required number was confirmed in the first-year international checklist.', 'Primarily in-person at the St. Paul/Minneapolis campuses; selected online and hybrid programmes are offered.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Other university-approved English proficiency routes"}'),
	('53ad0186-cf78-4e91-b7c0-787f196259f7', 'Boise State University', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Idaho''s largest public university","Offers international merit awards tied to high-school GPA"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health Sciences"}', 3.1, NULL, '{"Boise State online application","Official secondary-school transcripts and examination results","English-proficiency score or approved waiver","Passport identification page","Financial statement and sponsor evidence for I-20 processing after admission"}', 'https://www.boisestate.edu/global-international/apply/ia-international-first-year-admission/', 'Apply through Boise State''s international first-year online application. Submit school records, English-proficiency evidence and passport identification. SAT/ACT scores and recommendation letters are not generally required. New-to-college international merit scholarships require an eligible major and have a December 15 Fall scholarship deadline; the international priority application deadline is April 1. Some scholarship eligibility rules exclude applicants with 14 or more transferable post-secondary credits and selected majors/online programmes.', '0', 'A personal statement is optional; recommendation letters are welcomed but not required for the standard international first-year application.', 'New international freshmen may qualify for GPA-based awards with published annual values up to USD 17,000. The award amount depends on the GPA tier and eligible major; some scholarship funds are limited. Separate awards exist for students already enrolled at Boise State. These are partial merit awards, not full-cost aid.', NULL, '{"Boise State online application"}', 'USD 85', 'United States', '{"Boise, Idaho (main campus)"}', 'Public university', '{"SAT/ACT not required for standard international first-year admission","English examples: TOEFL iBT 68 on the previous scale or 4.0 on the new scale, IELTS Academic 6.0, Duolingo English Test 100, PTE Academic 50"}', NULL, 'GPA-based international merit scholarship; partial tuition support', 17000, 'No published maximum age. Some new-to-college awards require fewer than 14 transferable post-secondary credits; programme and visa rules apply.', 'Optional letters of recommendation; no required type or count for the standard international application.', 'In-person, online and selected hybrid undergraduate programmes; scholarship eligibility may exclude fully online/self-supported programmes.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Other Boise State-approved English proficiency routes"}'),
	('b6d5b0df-3828-40e9-97b5-edf0321bc6b0', 'University of Maryland, Baltimore County (UMBC)', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Carnegie R1 research university","Public research university known for STEM and undergraduate research"}', '{Undergraduate}', '{"Computer Science",Engineering,"Natural Sciences","Social Sciences","Arts and Humanities","Information Systems","Business Technology"}', NULL, NULL, '{"Common App","Official secondary-school transcripts and leaving examination results","English-proficiency score or approved waiver","Personal essay","Passport and financial documents for immigration processing","Optional recommendations (up to two may be submitted)"}', 'https://www.umbc.edu/admissions/undergraduate/first-year-students/how-to-apply/', 'Apply through the Common App and submit official academic records, English-proficiency evidence and the application essay. SAT/ACT are test-optional. To receive automatic merit scholarship consideration for Fall 2027, apply by November 1, 2026. First-year Regular Decision is February 1, 2027. Scholar Program applications have a separate January 15, 2027 deadline.', NULL, 'The Common App personal essay is required as part of the application platform. The #YouAreWelcomeHere scholarship requires a separate 500–1,000-word essay or a 2–5-minute video addressing intercultural learning.', 'UMBC offers competitive merit scholarships for international students. The #YouAreWelcomeHere programme offers two annual renewable scholarships covering 50% of tuition for eligible first-year international undergraduates. Other merit awards vary; the 50% scholarship is highly competitive and does not cover living expenses.', 50, '{"Common Application"}', 'USD 75', 'United States', '{"Baltimore County (Catonsville), Maryland"}', 'Public research university', '{"SAT/ACT test-optional","English examples: TOEFL iBT 80 on the previous scale or 4.5 on the new scale, IELTS Academic 6.5, Duolingo English Test 115, PTE Academic 53"}', NULL, 'Competitive merit scholarship; 50% tuition scholarship under #YouAreWelcomeHere', NULL, 'No published maximum age. Applicants must meet first-year or transfer classification and visa requirements.', 'Recommendations are optional; UMBC permits up to two, preferably academic references from teachers or counsellors.', 'Primarily in-person at the Catonsville campus; selected online/hybrid programmes are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Other UMBC-approved English proficiency routes"}'),
	('07b22a88-ba62-437d-8495-21cf59497446', 'University of Cincinnati', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Association of American Universities member","Public urban research university"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health Sciences","Music and Conservatory"}', 3.0, NULL, '{"Common App","Official secondary-school transcript and graduation certificate","English-proficiency evidence or approved waiver","Passport and financial records for immigration processing","Programme-specific prerequisites or portfolio/pre-screening where applicable","Optional recommendation letter"}', 'https://www.admissions.uc.edu/information/international/requirements/freshman.html', 'Apply using the Common App and submit academic records and English-proficiency results. SAT/ACT and recommendation letters are optional for general admission. The November 1 Early Action deadline gives priority consideration for merit scholarships; the general Fall rolling application deadline is March 1. English requirements and scholarship amounts may differ by college or campus. International students with post-secondary study after high school should follow the transfer route.', '0', 'Common App personal essay may be included; no additional universal international essay requirement was confirmed. College-specific supplemental questions may apply.', 'The International Outreach Award is a merit award for eligible international undergraduates, published in a range of approximately USD 5,000–15,000 per year at the Uptown campus. It is applied to the nonresident tuition surcharge, is competitive/eligibility-based and is not full-cost need-based aid. A GPA around 3.0 is listed for the award eligibility pathway.', NULL, '{"Common Application"}', NULL, 'United States', '{"Cincinnati, Ohio (Uptown/main campus)","Blue Ash, Ohio","Clermont County, Ohio"}', 'Public research university', '{"SAT/ACT optional for general international freshman admission","English score requirements vary by college; common examples include IELTS Academic 6.5, Duolingo English Test 100 and PTE Academic 53; TOEFL is accepted under the university''s current scale and programme rules"}', NULL, 'Merit-based international tuition award; partial nonresident tuition reduction', 15000, 'No published maximum age. Students who attended a college or university after high school are generally transfer applicants.', 'Recommendation letter is optional; no mandatory number for standard first-year admission.', 'In-person, online and hybrid undergraduate programmes across UC campuses; programme availability varies by campus.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Other college-approved English proficiency routes"}'),
	('c6aa0e55-99c7-40ff-8121-dbfd5694d5c9', 'Iowa State University', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Public land-grant research university","Association of American Universities member"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,Agriculture,"Natural Sciences","Social Sciences",Design,Education,"Veterinary Science"}', 3.0, NULL, '{"Iowa State undergraduate application","Official secondary-school transcripts and graduation certificate","English-proficiency test score or approved waiver","Passport identification and financial documents for I-20 processing","Course descriptions or additional academic records if requested"}', 'https://www.iastate.edu/admissions/undergraduate/international-students', 'Apply through Iowa State''s international undergraduate application and submit academic records, English-proficiency results and required financial/identity documents. SAT/ACT are not generally required for applicants educated outside the United States. International freshman merit scholarships are limited and competitive; applicants should complete the admission application and the scholarship application/OneApp by the published priority date. Students with post-secondary study should confirm transfer eligibility and scholarship rules.', NULL, 'No universal international freshman essay requirement was verified for the admission application; scholarship or programme applications may request essays.', 'International freshmen may compete for the Award of Achievement and Award of Distinction. Published ranges are approximately USD 5,000–10,000 per year for the Achievement award and USD 2,000–4,000 per year for the Distinction award, with limited awards and renewal rules. These are merit-based partial awards rather than need-based full-cost aid.', NULL, '{"Iowa State online undergraduate application"}', NULL, 'United States', '{"Ames, Iowa (main campus)"}', 'Public research university; land-grant institution', '{"SAT/ACT generally not required for international applicants educated outside the United States","English proficiency is required; accepted tests include TOEFL iBT, IELTS Academic, Duolingo English Test and PTE Academic, with pathway-specific minimums"}', NULL, 'Competitive international freshman merit scholarships; partial tuition support', 10000, 'No published maximum age. Applicants must meet secondary-school completion and visa requirements.', 'No general recommendation-letter requirement was confirmed for international undergraduate admission; programme or scholarship applications may request academic references.', 'Primarily in-person at Ames; selected online and hybrid undergraduate programmes are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Other Iowa State-approved English proficiency routes"}'),
	('05b2b736-b024-42fc-89e4-32aa68c7171a', 'Clarkson University', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Private research university with a strong engineering and technology focus","Offers undergraduate programmes in engineering, computing and applied sciences"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Data Science","Health Sciences","Arts and Sciences"}', NULL, NULL, '{"Clarkson freshman application or Common App","Official secondary-school transcripts and examination results","Two recommendation letters","Personal statement","English-proficiency score or approved waiver","Passport and financial documents for immigration processing"}', 'https://www.clarkson.edu/international-admissions-requirements', 'Apply through the Clarkson freshman application or Common App. Submit transcripts, the personal statement, two recommendations and English-proficiency evidence. SAT/ACT are optional. International first-year Early Decision is December 1 and Regular Decision is January 15. All admitted international undergraduate students are considered for general merit aid; separate applications may be needed for selected named scholarships or fellowships.', '2', 'A personal statement of approximately 250–500 words is requested; scholarship/fellowship programmes may require additional responses.', 'Clarkson considers admitted international undergraduates for partial merit scholarships. Additional selective programmes such as the Ignite Presidential Fellowship/Honors awards may offer larger funding, with separate criteria and application steps. Clarkson states that international students are not eligible for need-based financial aid. Do not treat the separately advertised maximum award as a guaranteed annual amount.', NULL, '{"Clarkson University freshman application","Common Application"}', 'USD 0 when applying through the Clarkson application or Common App', 'United States', '{"Potsdam, New York (main undergraduate campus)"}', 'Private nonprofit research university', '{"SAT/ACT optional for first-year admission","English examples: TOEFL iBT 4.5 on the new 1–6 scale, IELTS Academic 6.5, Duolingo English Test 115, PTE Academic 56"}', NULL, 'Institutional merit scholarships; selective competitive fellowships; partial tuition awards', NULL, 'No published maximum age. Applicants with previous college coursework should use the appropriate transfer application route.', 'Two recommendations are requested, generally including an academic teacher/counsellor reference; consult Clarkson''s current checklist for accepted recommender roles.', 'Primarily in-person at the Potsdam campus; selected online and hybrid offerings are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Other Clarkson-approved English proficiency routes"}'),
	('5e1ae7a9-2ffc-40fc-9d8d-589ed86ff0d9', 'Duquesne University', '{"International applicants from all countries, subject to credential evaluation and U.S. visa requirements"}', '{"Private Catholic university in Pittsburgh","Offers undergraduate programmes across health, business, liberal arts and sciences"}', '{Undergraduate}', '{Business,"Computer Science","Natural Sciences","Health Sciences","Liberal Arts",Education,Music,"Public Policy"}', NULL, NULL, '{"Common App, Future Focused application or other accepted undergraduate application","Official secondary-school transcript and graduation certificate","At least one recommendation letter","English-proficiency score or approved waiver","Passport and financial documents for I-20 processing","Programme-specific prerequisites where applicable"}', 'https://www.duq.edu/admission-and-aid/how-to-apply/undergraduate/freshman-application-process.php', 'Apply through Common App or one of Duquesne''s accepted undergraduate application routes. Submit academic records and English-proficiency evidence, plus at least one recommendation. Fall Early Action is November 15 and Regular Decision is January 15; most programmes continue on a rolling basis afterward if space remains. Competitive first-year university scholarship applications may have a January 15 deadline. Check programme-specific dates because some courses close earlier.', '1', 'Application essay/personal statement requirements depend on the chosen platform and programme; no separate universal international essay was confirmed in the retrieved requirements.', 'The Libermann Scholarship is an automatic-consideration merit award for eligible international undergraduates, with published values commonly ranging from USD 10,000 to 30,000 per year and renewable for up to four years. Duquesne does not offer full scholarships or need-based aid to international students under the cited policy; additional talent or athletic awards may be available.', NULL, '{"Common Application","Duquesne Future Focused application","Coalition application where offered"}', 'USD 0 for undergraduate applications', 'United States', '{"Pittsburgh, Pennsylvania (main campus)"}', 'Private nonprofit Catholic university', '{"SAT/ACT test-optional for many undergraduate programmes; programme-specific requirements may apply","English examples: TOEFL iBT 70 on the previous scale, IELTS Academic 6.0, Duolingo English Test 105, PTE Academic 48"}', NULL, 'Renewable international merit scholarship; partial tuition support', 30000, 'No published maximum age. Programme-specific admission rules and student visa requirements apply.', 'At least one recommendation from a teacher, counsellor or other person able to assess academic and personal strengths.', 'Primarily in-person at the Pittsburgh campus; selected online/hybrid programmes are available.', true, NULL, false, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Other Duquesne-approved English proficiency routes"}'),
	('26300506-322b-4b4d-a181-e76e36dc4645', 'Florida Atlantic University', '{"International applicants from all countries; the President''s International Scholarship is for eligible F-1 or J-1 visa students"}', '{"Carnegie R1 research university","Multi-campus public university in South Florida"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health Sciences"}', 3.5, NULL, '{"Common App or FAU-approved undergraduate application","Official secondary-school academic records and examination results","Course-by-course credential evaluation where required","SAT/ACT/CLT scores for applicants subject to the international freshman test rule","English-proficiency evidence","Passport and financial documents for immigration processing"}', 'https://www.fau.edu/global/international/', 'Apply through Common App as an international first-year applicant, submit academic records and English-proficiency evidence, and provide SAT/ACT/CLT scores where required. The President''s International Scholarship is limited and competitive; eligible applicants are automatically considered after admission if the completed application is received by the scholarship deadlines. Published Fall scholarship dates are January 15 priority and March 15 regular. Students with college/university credits may be classified as transfer applicants and may not qualify for the freshman award.', NULL, 'Common App personal essay or application writing may apply; no separate universal scholarship essay was verified for the President''s International Scholarship.', 'The President''s International Scholarship is a limited, competitive award of USD 6,000 per year, renewable for up to four years for qualifying freshmen holding F-1 or J-1 status. A minimum 3.5 GPA and qualifying standardized-test/English criteria are part of the published scholarship profile. It is partial merit funding, not a full-cost award.', NULL, '{"Common Application","FAU online application where available for the relevant applicant type"}', 'USD 30', 'United States', '{"Boca Raton, Florida (main campus)","Davie, Florida","Fort Lauderdale, Florida","Jupiter, Florida","Fort Pierce, Florida","Dania Beach, Florida"}', 'Public research university', '{"SAT/ACT/CLT scores are required for international applicants with fewer than 60 transferable credits under the published rule; the cited middle-50% profile is not a minimum admission cutoff","English-proficiency evidence is required for applicants who do not qualify for an exemption"}', NULL, 'Competitive renewable international merit scholarship; partial annual award', 6000, 'No published maximum age. Freshman scholarship is restricted to qualifying first-time degree-seeking students; post-secondary study may change the applicant category.', 'No universal recommendation-letter requirement was confirmed for standard international freshman admission.', 'In-person, online and hybrid undergraduate offerings across FAU campuses; F-1 students must meet in-person study requirements.', true, NULL, true, '{"TOEFL iBT","IELTS Academic","Duolingo English Test","PTE Academic","Cambridge English qualifications","Approved English-medium education exemptions"}'),
	('746008a4-5d92-4c87-b92c-52050b4c1540', 'University of Alabama at Birmingham (UAB)', '{"International applicants living outside the United States; the USD 7,500 International Scholarship requires foreign secondary-school completion and anticipated F-1 status"}', '{"Carnegie R1 research university","Major academic medical and health-sciences centre"}', '{Undergraduate}', '{Engineering,"Computer Science",Business,"Natural Sciences","Social Sciences","Arts and Humanities",Education,"Health Professions"}', 3.0, NULL, '{"UAB/INTO UAB international undergraduate application route where applicable","Official secondary-school transcripts and graduation certificate","English-proficiency score or approved waiver","Passport identification page","Proof of financial support for I-20 processing","Additional programme-specific requirements where applicable"}', 'https://www.uab.edu/admissions/apply/international/freshman', 'International students applying from outside the United States with foreign secondary-school credentials should follow UAB''s international application route, which may direct applicants through INTO UAB. Submit transcripts, English proficiency and identity/financial documents. The USD 7,500 International Scholarship is automatically considered after admission but requires the applicant to be living outside the U.S., have graduated from a foreign high school within the permitted period, have at least a 3.0 GPA, have no post-secondary enrolment and anticipate an F-1 visa. Students must be accepted by May 1 for the August intake.', NULL, 'No universal international undergraduate essay requirement was confirmed in the retrieved application checklist; programme-specific requirements may apply.', 'UAB''s International Scholarship is USD 7,500 per year, renewable for up to four years/eight semesters, and is awarded on a first-come, first-served basis as funds remain. It excludes students receiving government scholarships or other external sponsorship and is restricted to new first-year students meeting the no-prior-post-secondary-credit condition. It is partial funding, not a full-cost award.', NULL, '{"INTO UAB international application route for applicants living outside the United States","UAB online application or Common Application for eligible applicant categories"}', 'USD 40', 'United States', '{"Birmingham, Alabama (main campus)"}', 'Public research university', '{"SAT/ACT are not a universal requirement for the international scholarship described","English examples: TOEFL iBT 77, IELTS Academic 6.0 with minimum subscores, Duolingo English Test 120, TOEFL Essentials 8.5"}', NULL, 'Renewable fixed-value international merit scholarship; partial tuition support', 7500, 'No published maximum age. The International Scholarship is limited to applicants completing secondary school outside the U.S. within three years before intake and who have not enrolled in post-secondary education.', 'No universal recommendation-letter requirement was confirmed for the general international undergraduate route.', 'Primarily in-person at Birmingham; selected online and hybrid programmes are available, but F-1 enrolment rules apply.', true, NULL, false, '{"TOEFL iBT","TOEFL Essentials","IELTS Academic","Duolingo English Test","International English Language Assessment (IELA)","Other UAB-approved English proficiency routes"}'),
	('e6b42b0f-bd2c-4715-bf83-68c3b5738b38', 'Harvard University', '{"all over the world (international applicants are welcome)"}', '{Harvard,"the first college in the American colonies","founded in Cambridge","Massachusetts on October 28","1636; oldest corporation in the Western Hemisphere"}', '{"undergraduate (first-year / transfer)"}', '{}', NULL, NULL, '{"School Report with counselor letter","high school transcript","2 Teacher Reports","Midyear School Report","Final School Report (for admitted students); for transfer: College/Dean''s/Registrar''s report","Official College Transcript","2 College Instructor Recommendations","Official High School Transcript; SAT or ACT; $95 fee or fee waiver"}', 'https://www.commonapp.org/explore/harvard-university', '', '2', 'Five required short-answer questions, each with a 150 word limit, covering life experiences, a time of strong disagreement, extracurricular activities, future aspirations, and top 3 things roommates might like to know.', 'Our scholarships are designed to cover 100% of your demonstrated financial need using a combination of scholarship funds and student employment, as well as any awards earned from outside sources. Loans are never required, but are available to interested families.', NULL, '{"Common App"}', '$95 fee (or request a fee waiver)', 'United States', '{"Montag Hall","355 Galvez Street","United States of America"}', 'Private', '{}', '', '', NULL, '', '', '', NULL, true, true, '{TOEFL,IELTS,"and Duolingo (cannot be used to meet the standardized testing requirement","but can be submitted for review)"}');
